def get_best_schedule(workload, num_seqs):
    """
    Conflict-graph decomposition + exact DP on small components, with
    hybrid local search and adaptive iterated local search on the rest.

    1. Build key->transaction incidence; transactions sharing no key with
       any other txn ("free" txns) add no conflict cost wherever placed.
    2. Split the conflict graph into connected components (union-find);
       components are conflict-independent and scheduled separately.
    3. Components with <= 12 txns are solved EXACTLY via Held-Karp
       bitmask DP over prefix orderings using the true cost function.
    4. Larger components: multi-restart exact-cost greedy + hybrid local
       search (2-opt swaps, or-opt reinsertion, segment reversal).
    5. Concatenate component schedules, greedily reinsert free txns,
       then polish the full sequence and run adaptive ILS (growing
       perturbation kicks, destroy-and-repair, plateau sideways moves)
       under the remaining time budget.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns

    # ---------- key incidence ----------
    def txn_keys(t):
        for attr in ("txns", "transactions", "txn_list"):
            data = getattr(workload, attr, None)
            if data is None:
                continue
            item = data[t] if isinstance(data, (list, tuple)) else data.get("txn%d" % t)
            if item is None and isinstance(data, dict):
                for k in (t, str(t), "txn%d" % t):
                    if k in data:
                        item = data[k]
                        break
            if item is None:
                continue
            keys = set()
            if isinstance(item, str):
                toks = item.split()
            elif isinstance(item, (list, tuple)):
                toks = [str(x) for x in item]
            else:
                toks = []
            for tok in toks:
                parts = tok.split("-")
                if len(parts) == 2:
                    keys.add(parts[1])
            if keys or toks:
                return keys
        return set()

    keys_of = {}
    key_map = {}
    for t in range(n):
        ks = txn_keys(t)
        keys_of[t] = ks
        for k in ks:
            key_map.setdefault(k, set()).add(t)

    free_txns = [t for t in range(n)
                 if all(len(key_map[k]) == 1 for k in keys_of[t])]
    free_set = set(free_txns)
    core = [t for t in range(n) if t not in free_set]

    # ---------- connected components (union-find) ----------
    parent = {t: t for t in core}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for k, ts in key_map.items():
        ts = [x for x in ts if x not in free_set]
        for i in range(1, len(ts)):
            a, b = find(ts[0]), find(ts[i])
            if a != b:
                parent[a] = b
    groups = {}
    for t in core:
        groups.setdefault(find(t), []).append(t)
    components = [sorted(g) for g in groups.values()]
    components.sort(key=len)

    def exact_dp(comp, deadline):
        m = len(comp)
        if m > 12:
            return None
        full = (1 << m) - 1
        dp = {0: (0, [])}
        order_masks = sorted(range(1, full + 1), key=lambda x: bin(x).count("1"))
        for mask in order_masks:
            if time.time() - start_time > deadline:
                return None
            best = None
            for i in range(m):
                bit = 1 << i
                if not (mask & bit):
                    continue
                prev = mask ^ bit
                if prev not in dp:
                    continue
                pc, porder = dp[prev]
                seq = porder + [comp[i]]
                c = workload.get_opt_seq_cost(seq)
                if best is None or c < best[0]:
                    best = (c, seq)
            if best is not None:
                dp[mask] = best
        return dp.get(full)

    def greedy_comp(comp, start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in comp if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
                c = workload.get_opt_seq_cost(seq + [t])
                scored.append((c, random.random() if noise else t, t))
            scored.sort()
            pick = scored[0][2]
            if noise and len(scored) > 1 and random.random() < noise:
                pick = scored[1][2]
            seq.append(pick)
            remaining.remove(pick)
        return workload.get_opt_seq_cost(seq), seq

    def local_search(seq, cost, deadline=None):
        m = len(seq)
        improved = True
        while improved and time.time() - start_time < time_budget:
            improved = False
            for i in range(m - 1):
                for j in range(i + 1, m):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    if deadline is not None and time.time() > deadline:
                        return cost, seq
                    seq[i], seq[j] = seq[j], seq[i]
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i], seq[j] = seq[j], seq[i]
            for i in range(m):
                if time.time() - start_time >= time_budget:
                    return cost, seq
                if deadline is not None and time.time() > deadline:
                    return cost, seq
                t = seq.pop(i)
                for j in range(m):
                    if j == i:
                        continue
                    seq.insert(j, t)
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                        break
                    seq.pop(j)
                else:
                    seq.insert(i, t)
            for i in range(m - 1):
                for j in range(i + 2, min(i + 12, m)):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    if deadline is not None and time.time() > deadline:
                        return cost, seq
                    seq[i:j + 1] = seq[i:j + 1][::-1]
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i:j + 1] = seq[i:j + 1][::-1]
        return cost, seq

    # ---------- solve each component ----------
    comp_schedules = []
    for comp in components:
        m = len(comp)
        res = None
        if m <= 12:
            res = exact_dp(comp, start_time + time_budget * 0.5)
        if res is not None:
            comp_schedules.append(res[1])
            continue
        best_c, best_s = None, None
        starts = comp if m <= 8 else [comp[i] for i in range(0, m, max(1, m // 8))][:8]
        for s in starts:
            if time.time() - start_time >= time_budget * 0.55:
                break
            c, seq = greedy_comp(comp, s)
            if best_c is None or c < best_c:
                best_c, best_s = c, seq
        while time.time() - start_time < time_budget * 0.5:
            s = random.choice(comp)
            c, seq = greedy_comp(comp, s, noise=0.15)
            if c < best_c:
                best_c, best_s = c, seq
        best_c, best_s = local_search(best_s, best_c)
        comp_schedules.append(best_s)

    # ---------- assemble + reinsert free txns ----------
    seq = []
    for cs in comp_schedules:
        seq.extend(cs)
    for t in free_txns:
        best_c, best_j = None, 0
        for j in range(len(seq) + 1):
            seq.insert(j, t)
            c = workload.get_opt_seq_cost(seq)
            if best_c is None or c < best_c:
                best_c, best_j = c, j
            seq.pop(j)
        seq.insert(best_j, t)

    best_cost = workload.get_opt_seq_cost(seq)
    best_seq = seq

    best_cost, best_seq = local_search(best_seq, best_cost)

    # ---------- adaptive ILS on full sequence ----------
    pool = [(best_cost, best_seq)]
    kick = 2
    while time.time() - start_time < time_budget:
        if random.random() < 0.5:
            base = best_seq
        else:
            base = random.choice(pool)[1]
        cand = base[:]
        mode = random.random()
        if mode < 0.3:
            for _ in range(kick):
                i, j = random.sample(range(n), 2)
                cand[i], cand[j] = cand[j], cand[i]
        elif mode < 0.6:
            for _ in range(kick):
                i, j = sorted(random.sample(range(n), 2))
                cand[i:j + 1] = cand[i:j + 1][::-1]
        elif mode < 0.8:
            for _ in range(kick):
                i = random.randrange(n)
                t = cand.pop(i)
                cand.insert(random.randrange(n), t)
        else:
            # destroy-and-repair: remove a small block and greedily
            # reinsert each removed txn at its true-cost-best position
            i = random.randrange(n)
            length = min(n, 3 + random.randrange(4))
            removed = cand[i:i + length]
            del cand[i:i + length]
            for t in removed:
                best_j, best_c2 = 0, None
                for j in range(len(cand) + 1):
                    cand.insert(j, t)
                    c2 = workload.get_opt_seq_cost(cand)
                    if best_c2 is None or c2 < best_c2:
                        best_c2, best_j = c2, j
                    cand.pop(j)
                cand.insert(best_j, t)
        remaining = time_budget - (time.time() - start_time)
        deadline = time.time() + min(5.0, remaining * 0.25)
        c, cand = local_search(cand, workload.get_opt_seq_cost(cand),
                               deadline=deadline)
        if c < best_cost:
            best_cost, best_seq = c, cand
            kick = 2
        elif c == best_cost and random.random() < 0.3:
            best_seq = cand
            kick = 2
        else:
            kick = min(kick + 1, 6)
        if len(pool) < 8 or c < pool[-1][0]:
            pool.append((c, cand))
            pool.sort(key=lambda x: x[0])
            pool = pool[:8]

    assert len(set(best_seq)) == workload.num_txns
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")

